#include "../platform/3ds/source/presentation_3ds.hpp"
#include "starfox/render/software_renderer.hpp"

#include <cmath>
#include <iostream>
#include <stdexcept>

using namespace starfox;

int main() try {
    // A Q15-rounded quaternion rotation generated by the existing production
    // interpolation routine. R^T R must remain approximately the identity.
    // The third column's squared length rounds to +32768, not -32768.
    const simulation::MatrixQ15 rotation{
        1814, 27860, -17155,
        30849, 4268, 10192,
        10900, -16714, -25992};
    const auto object = simulation::transpose_q15(rotation);
    const auto native = simulation::multiply_matrix_q15(object, rotation);
    if (native[8] != -32768)
        throw std::runtime_error("fixture no longer reaches native Q15 wrap");
    for (const auto alpha : {0.125, 1.0 / 3.0, 0.5, 2.0 / 3.0, 0.875}) {
        const auto actual = platform_3ds::compose_model_view_matrix(
            object, rotation, alpha);
        for (unsigned i = 0; i < 9; ++i) {
            if (i % 4 == 0 ? actual[i] < 32765 : std::abs(int(actual[i])) > 2)
                throw std::runtime_error("interpolated R^T R reflected the model");
        }
        assets::Shape shape;
        shape.vertices = {{-20, -10, -40}, {20, -10, 40}, {0, 30, 0}};
        assets::Face face;
        face.visibility_index = -1;
        face.vertex_indices = {0, 1, 2};
        face.colour_id = 7;
        shape.faces.push_back(face);
        render::RenderPose pose;
        pose.use_rotation_matrix = true;
        pose.rotation_matrix = actual;
        pose.z = 420;
        render::Framebuffer frame(224, 192);
        render::RenderDiagnostics trace;
        render::SoftwareRenderer().draw(shape, pose, frame, true,
            nullptr, nullptr, &trace);
        if (trace.polygons.size() != 1
            || std::abs(trace.polygons[0].camera[0][2] - 380.0) > 3.0
            || std::abs(trace.polygons[0].camera[1][2] - 460.0) > 3.0)
            throw std::runtime_error("actual raster geometry inverted depth");
    }
    for (const auto alpha : {0.0, 1.0})
        if (platform_3ds::compose_model_view_matrix(object, rotation, alpha) != native)
            throw std::runtime_error("completed source matrix arithmetic changed");
    const simulation::MatrixQ15 held{32766, 0, 0, 0, 32766, 0, 0, 0, 32766};
    for (const auto alpha : {0.0, 0.25, 0.5, 0.75, 1.0})
        if (platform_3ds::compose_model_view_matrix(held, held, alpha)
                != simulation::multiply_matrix_q15(held, held))
            throw std::runtime_error("held rotation changed at fractional phases");
    std::cout << "3DS fractional Q15 composition: analytical identity, raster depths, "
                 "native endpoints and held poses passed\n";
    return 0;
} catch (const std::exception& error) {
    std::cerr << error.what() << '\n';
    return 1;
}
